            + ',' + clBatCh.toFixed(3) + ',' + clBatCh.toFixed(3) + ',' + clBatDis.toFixed(3) + ',' + clLoad.toFixed(3) + ',' + (haRow.genPrice||0).toFixed(4) + ',' + (haRow.fitPrice||0).toFixed(4) + ',' + (haRow.aemoPrice||0).toFixed(4) + ',' + pe + ',' + clSolar.toFixed(3) + ',' + clImp.toFixed(3);
        newRows.push(row);
        anchorImp = clImp; anchorExp = clExp; anchorBatCharge = clBatCh; anchorBatDischarge = clBatDis; anchorLoad = clLoad; anchorSolar = clSolar;
    }
